PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL,description TEXT,owner_person_id TEXT,status TEXT NOT NULL DEFAULT 'planning',priority TEXT NOT NULL DEFAULT 'normal',start_date TEXT,end_date TEXT,planned_budget_cents INTEGER NOT NULL DEFAULT 0,actual_cost_cents INTEGER NOT NULL DEFAULT 0,created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_person_id) REFERENCES hr_people(id) ON DELETE SET NULL,UNIQUE(organization_id,dba_id,code),CHECK(status IN ('planning','active','on_hold','completed','cancelled')),CHECK(priority IN ('low','normal','high','critical')),CHECK(planned_budget_cents>=0),CHECK(actual_cost_cents>=0),CHECK(start_date IS NULL OR end_date IS NULL OR start_date<=end_date));
CREATE INDEX IF NOT EXISTS idx_projects_scope ON projects(organization_id,dba_id,status,priority,start_date);
CREATE TABLE IF NOT EXISTS project_members(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,project_id TEXT NOT NULL,person_id TEXT NOT NULL,role_name TEXT,allocation_percent REAL NOT NULL DEFAULT 100,status TEXT NOT NULL DEFAULT 'active',created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(person_id) REFERENCES hr_people(id) ON DELETE RESTRICT,UNIQUE(project_id,person_id),CHECK(allocation_percent>=0 AND allocation_percent<=100),CHECK(status IN ('active','inactive')));
CREATE INDEX IF NOT EXISTS idx_project_members_scope ON project_members(organization_id,dba_id,project_id,status);
CREATE TABLE IF NOT EXISTS project_milestones(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,project_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,due_date TEXT,status TEXT NOT NULL DEFAULT 'open',completed_at TEXT,created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,CHECK(status IN ('open','in_progress','completed','cancelled')));
CREATE INDEX IF NOT EXISTS idx_project_milestones_scope ON project_milestones(organization_id,dba_id,project_id,status,due_date);
CREATE TABLE IF NOT EXISTS project_tasks(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,project_id TEXT NOT NULL,milestone_id TEXT,title TEXT NOT NULL,description TEXT,assignee_person_id TEXT,priority TEXT NOT NULL DEFAULT 'normal',status TEXT NOT NULL DEFAULT 'open',start_date TEXT,due_date TEXT,estimated_minutes INTEGER NOT NULL DEFAULT 0,actual_minutes INTEGER NOT NULL DEFAULT 0,completed_at TEXT,created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(milestone_id) REFERENCES project_milestones(id) ON DELETE SET NULL,FOREIGN KEY(assignee_person_id) REFERENCES hr_people(id) ON DELETE SET NULL,CHECK(priority IN ('low','normal','high','critical')),CHECK(status IN ('open','in_progress','blocked','completed','cancelled')),CHECK(estimated_minutes>=0),CHECK(actual_minutes>=0),CHECK(start_date IS NULL OR due_date IS NULL OR start_date<=due_date));
CREATE INDEX IF NOT EXISTS idx_project_tasks_scope ON project_tasks(organization_id,dba_id,project_id,status,priority,due_date);
CREATE TABLE IF NOT EXISTS project_costs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,dba_id TEXT NOT NULL,project_id TEXT NOT NULL,cost_date TEXT NOT NULL,category TEXT,description TEXT,amount_cents INTEGER NOT NULL,reference_type TEXT,reference_id TEXT,reference TEXT,created_by_user_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,CHECK(amount_cents>=0));
CREATE INDEX IF NOT EXISTS idx_project_costs_scope ON project_costs(organization_id,dba_id,project_id,cost_date DESC);
